17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.BusinessDay;
30	import org.springframework.samples.petclinic.model.CustomerCode;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        LocalDate registrationDate = BusinessDay.adjust(
108	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
109	        owner.setRegistrationDate(registrationDate);
110	        Collection<Owner> owners = this.clinicService.findAllOwners().stream().filter(existing -> !existing.isDeleted()).toList();
111	        if (owners.stream().filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() >= 100) {
112	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
113	        }
114	        if (owners.stream().anyMatch(existing -> existing.getIdentityKey().equals(owner.getIdentityKey()))
115	                || owners.stream().filter(existing -> existing.getCity().equalsIgnoreCase(owner.getCity())).count() >= 50) {
116	            return new ResponseEntity<>(HttpStatus.CONFLICT);
117	        }
118	        owner.setNamesakeCount((int) owners.stream()
119	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(owner.getFirstName())
120	                && existing.getLastName().equalsIgnoreCase(owner.getLastName()))
121	            .count());
122	        if (owners.stream().anyMatch(existing -> sameHousehold(existing, owner))
123	                && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
124	            return new ResponseEntity<>(HttpStatus.CONFLICT);
125	        }
126	        owner.setHouseholdMemberCount(1 + (int) owners.stream().filter(existing -> sameHousehold(existing, owner)).count());
127	        owner.setCustomerCode(CustomerCode.of(owner, owners));
128	        owner.setPossibleDuplicate(false);
129	        owner.setPossibleDuplicateOf(null);
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        ownerDto.setBulkSignupWarning(owners.stream()
133	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate())).count() > 80);
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    /** Two owners share a household when they resolve to the same {@link Owner#getHouseholdId()}
140	     *  (matching last name and postcode). */
141	    private static boolean sameHousehold(Owner a, Owner b) {
142	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
148	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
149	        if (currentOwner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        currentOwner.setAddress(ownerFieldsDto.getAddress());
153	        currentOwner.setCity(ownerFieldsDto.getCity());
154	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
155	        currentOwner.setLastName(ownerFieldsDto.getLastName());
156	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        owner.setDeleted(true);
170	        this.clinicService.saveOwner(owner);
171	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Pet pet = petMapper.toPet(petFieldsDto);
183	        owner.setId(ownerId);
184	        pet.setOwner(owner);
185	        pet.getType().setName(null);
186	        this.clinicService.savePet(pet);
187	        PetDto petDto = petMapper.toPetDto(pet);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
189	            .buildAndExpand(pet.getId()).toUri());
190	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner != null) {
198	            Pet currentPet = this.clinicService.findPetById(petId);
199	            if (currentPet != null) {
200	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
201	                currentPet.setName(petFieldsDto.getName());
202	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
203	                this.clinicService.savePet(currentPet);
204	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
213	        HttpHeaders headers = new HttpHeaders();
214	        Visit visit = visitMapper.toVisit(visitFieldsDto);
215	        Pet pet = new Pet();
216	        pet.setId(petId);
217	        visit.setPet(pet);
218	        this.clinicService.saveVisit(visit);
219	        VisitDto visitDto = visitMapper.toVisitDto(visit);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
221	            .buildAndExpand(visit.getId()).toUri());
222	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
223	    }
224	
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner != null) {
231	            Pet pet = owner.getPet(petId);
232	            if (pet != null) {
233	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	}
