16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Transient
44	    private String flatAddress;
45	
46	    @Transient
47	    private String addressLine1;
48	
49	    @Transient
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "postcode")
65	    private String postcode;
66	
67	    @Column(name = "registration_date", columnDefinition = "DATE")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date", columnDefinition = "DATE")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "customer_code")
74	    private String customerCode;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "household_member_count")
80	    private Integer householdMemberCount;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @Column(name = "deleted")
89	    private boolean deleted;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    /** Default an absent registration date to the server's current date on first persist. */
95	    @PrePersist
96	    void defaultRegistrationDate() {
97	        if (this.registrationDate == null) {
98	            this.registrationDate = LocalDate.now();
99	        }
100	    }
101	
102	    public LocalDate getRegistrationDate() {
103	        return this.registrationDate;
104	    }
105	
106	    public void setRegistrationDate(LocalDate registrationDate) {
107	        this.registrationDate = registrationDate;
108	    }
109	
110	    public LocalDate getBirthDate() {
111	        return this.birthDate;
112	    }
113	
114	    public void setBirthDate(LocalDate birthDate) {
115	        this.birthDate = birthDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    /** Stable identifier shared by owners of the same household (matching last name and postcode). */
123	    @Transient
124	    public String getHouseholdId() {
125	        return HouseholdId.of(getLastName(), this.postcode);
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    /** Derived duplicate-detection key: normalized telephone, email (or empty) and household id
133	     *  joined with {@code '|'}. Two owners are duplicates only when their whole key matches, so a
134	     *  shared telephone alone (with matching email) is a collision regardless of household. */
135	    @Transient
136	    public String getIdentityKey() {
137	        return (this.telephone == null ? "" : this.telephone) + "|"
138	            + (this.email == null ? "" : this.email) + "|";
139	    }
140	
141	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
142	    @Transient
143	    public String getMembershipNumber() {
144	        return MembershipNumber.of(this.customerCode, this.registrationDate);
145	    }
146	
147	    /** Luhn check digit over the digits of the {@code customerCode}. */
148	    @Transient
149	    public Integer getCheckDigit() {
150	        return CheckDigit.of(this.customerCode);
151	    }
152	
153	    public Integer getNamesakeCount() {
154	        return this.namesakeCount;
155	    }
156	
157	    public void setNamesakeCount(Integer namesakeCount) {
158	        this.namesakeCount = namesakeCount;
159	    }
160	
161	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
162	     *  captured when the owner was created, including this owner. */
163	    public Integer getHouseholdMemberCount() {
164	        return this.householdMemberCount;
165	    }
166	
167	    public void setHouseholdMemberCount(Integer householdMemberCount) {
168	        this.householdMemberCount = householdMemberCount;
169	    }
170	
171	    /** True when this owner, at creation, shared an existing owner's last name and postcode
172	     *  but had a different telephone (a soft, non-hard duplicate). */
173	    public Boolean getPossibleDuplicate() {
174	        return this.possibleDuplicate;
175	    }
176	
177	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
178	        this.possibleDuplicate = possibleDuplicate;
179	    }
180	
181	    /** Id of the existing owner this owner possibly duplicates, when {@link #getPossibleDuplicate()}. */
182	    public Integer getPossibleDuplicateOf() {
183	        return this.possibleDuplicateOf;
184	    }
185	
186	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
187	        this.possibleDuplicateOf = possibleDuplicateOf;
188	    }
189	
190	    /** True once the owner has been soft-deleted; the row is retained but ignored by the
191	     *  create endpoint's duplicate and identity checks. False for a newly created owner. */
192	    public boolean isDeleted() {
193	        return this.deleted;
194	    }
195	
196	    public void setDeleted(boolean deleted) {
197	        this.deleted = deleted;
198	    }
199	
200	    public String getEmail() {
201	        return this.email;
202	    }
203	
204	    public void setEmail(String email) {
205	        this.email = email == null ? null : email.toLowerCase();
206	    }
207	
208	    public String getAddress() {
209	        return this.address;
210	    }
211	
212	    public void setAddress(String address) {
213	        this.flatAddress = AddressNormalizer.normalize(address);
214	        this.address = composeAddress();
215	    }
216	
217	    public String getAddressLine1() {
218	        return this.addressLine1;
219	    }
220	
221	    public void setAddressLine1(String addressLine1) {
222	        this.addressLine1 = AddressNormalizer.normalize(addressLine1);
223	        this.address = composeAddress();
224	    }
225	
226	    public String getAddressLine2() {
227	        return this.addressLine2;
228	    }
229	
230	    public void setAddressLine2(String addressLine2) {
231	        this.addressLine2 = AddressNormalizer.normalize(addressLine2);
232	        this.address = composeAddress();
233	    }
234	
235	    /** Prefer the structured lines when {@code addressLine1} is present (line 2 appended after a
236	     *  single space), otherwise fall back to the flat address, so all address readers stay consistent. */
237	    private String composeAddress() {
238	        if (this.addressLine1 == null || this.addressLine1.isBlank()) {
239	            return this.flatAddress;
240	        }
241	        return this.addressLine2 == null ? this.addressLine1 : this.addressLine1 + " " + this.addressLine2;
242	    }
243	
244	    public String getPostcode() {
245	        return this.postcode;
246	    }
247	
248	    public void setPostcode(String postcode) {
249	        this.postcode = postcode;
250	    }
251	
252	    public String getCity() {
253	        return this.city;
254	    }
255	
256	    public void setCity(String city) {
257	        this.city = city;
258	    }
259	
260	    public String getTelephone() {
261	        return this.telephone;
262	    }
263	
264	    public void setTelephone(String telephone) {
265	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
266	    }
267	
268	    protected Set<Pet> getPetsInternal() {
269	        if (this.pets == null) {
270	            this.pets = new HashSet<>();
271	        }
272	        return this.pets;
273	    }
274	
275	    protected void setPetsInternal(Set<Pet> pets) {
276	        this.pets = pets;
277	    }
278	
279	    public List<Pet> getPets() {
280	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
281	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
282	        return Collections.unmodifiableList(sortedPets);
283	    }
284	
285	    public void setPets(List<Pet> pets) {
286	        this.pets = new HashSet<>(pets);
287	    }
288	
289	    public void addPet(Pet pet) {
290	        getPetsInternal().add(pet);
291	        pet.setOwner(this);
292	    }
293	
294	    /**
295	     * Return the Pet with the given name, or null if none found for this Owner.
296	     *
297	     * @param name to test
298	     * @return true if pet name is already in use
299	     */
300	    public Pet getPet(String name) {
301	        return getPet(name, false);
302	    }
303	
304	    /**
305	     * Return the Pet with the given name, or null if none found for this Owner.
306	     *
307	     * @param name to test
308	     * @return true if pet name is already in use
309	     */
310	    public Pet getPet(String name, boolean ignoreNew) {
311	        name = name.toLowerCase();
312	        for (Pet pet : getPetsInternal()) {
313	            if (!ignoreNew || !pet.isNew()) {
314	                String compName = pet.getName();
315	                compName = compName.toLowerCase();
316	                if (compName.equals(name)) {
317	                    return pet;
318	                }
319	            }
320	        }
321	        return null;
322	    }
323	
324	    public Pet getPet(Integer petId) {
325	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
326	    }
327	
328	    @Override
329	    public String toString() {
330	        return new ToStringCreator(this)
331	
332	            .append("id", this.getId())
333	            .append("new", this.isNew())
334	            .append("lastName", this.getLastName())
335	            .append("firstName", this.getFirstName())
336	            .append("address", this.address)
337	            .append("city", this.city)
338	            .append("telephone", this.telephone)
339	            .toString();
340	    }
341	}
