1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import java.util.Map;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	import org.springframework.samples.petclinic.model.PhoneNumbers;
9	
10	/**
11	 * Checks the national-number length of a telephone once normalised to E.164, per country code.
12	 */
13	public class E164NationalLengthValidator implements ConstraintValidator<E164NationalLength, String> {
14	
15	    /** Country code (with leading '+') to the number of national digits it requires. */
16	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("+61", 9, "+1", 10);
17	
18	    @Override
19	    public boolean isValid(String raw, ConstraintValidatorContext context) {
20	        if (raw == null || raw.isBlank()) {
21	            return true;
22	        }
23	        String e164 = PhoneNumbers.toE164(raw);
24	        for (Map.Entry<String, Integer> rule : NATIONAL_DIGITS.entrySet()) {
25	            if (e164.startsWith(rule.getKey())) {
26	                return e164.length() - rule.getKey().length() == rule.getValue();
27	            }
28	        }
29	        return true;
30	    }
31	}
