1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import java.util.Set;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	/**
9	 * Rejects an email whose domain is a known disposable-mail provider. A blank or absent email,
10	 * or one with no domain part, is left to the field-level format constraint and accepted here.
11	 */
12	public class NonDisposableEmailValidator implements ConstraintValidator<NonDisposableEmail, String> {
13	
14	    private static final Set<String> BLOCKED = Set.of(
15	        "mailinator.com", "tempmail.com", "guerrillamail.com");
16	
17	    @Override
18	    public boolean isValid(String email, ConstraintValidatorContext context) {
19	        if (email == null || email.isBlank()) {
20	            return true;
21	        }
22	        int at = email.lastIndexOf('@');
23	        if (at < 0) {
24	            return true;
25	        }
26	        return !BLOCKED.contains(email.substring(at + 1).toLowerCase());
27	    }
28	}
