45	    }
46	
47	    public void setFirstName(String firstName) {
48	        this.firstName = firstName;
49	    }
50	
51	    public String getLastName() {
52	        return this.lastName;
53	    }
54	
55	    public void setLastName(String lastName) {
56	        this.lastName = lastName;
57	    }
58	
59	    public String getTitle() {
60	        return this.title;
61	    }
62	
63	    public void setTitle(String title) {
64	        this.title = title;
65	    }
66	
67	    /** Title and last name joined by a space, or just the last name when no title was given. */
68	    @Transient
