16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.util.Collection;
21	
22	/**
23	 * Builds an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: the
24	 * region derived from the owner's postcode, and the first 8 upper-case hex
25	 * characters of {@code SHA-256(normalizedTelephone + lastName)}, e.g.
26	 * {@code NSW-1A2B3C4D}.
27	 */
28	public final class CustomerCode {
29	
30	    private CustomerCode() {
31	    }
32	
33	    /**
34	     * @param owner          the owner being coded (its postcode, telephone and last name are used)
35	     * @param existingOwners the current owners (unused; identity no longer depends on other owners)
36	     * @return the formatted customer code, e.g. {@code NSW-1A2B3C4D}
37	     */
38	    public static String of(Owner owner, Collection<Owner> existingOwners) {
39	        String region = Locality.of(owner.getCity(), owner.getPostcode());
40	        String base = region + "-" + hash8(owner.getTelephone() + owner.getLastName());
41	        return deduplicate(base, existingOwners);
42	    }
43	
44	    /** Appends {@code -<n>} with the smallest {@code n >= 2} that avoids any existing
45	     *  owner's customer code, or returns {@code base} unchanged when already unique. */
46	    private static String deduplicate(String base, Collection<Owner> existingOwners) {
47	        java.util.Set<String> taken = new java.util.HashSet<>();
48	        for (Owner existing : existingOwners) {
49	            taken.add(existing.getCustomerCode());
50	        }
51	        String unique = base;
52	        for (int n = 2; taken.contains(unique); n++) {
53	            unique = base + "-" + n;
54	        }
55	        return unique;
56	    }
57	
58	    /** The {@code <REGION>} component of a customer code, or {@code "UNKNOWN"} when absent. */
59	    public static String regionOf(String customerCode) {
60	        int dash = customerCode == null ? -1 : customerCode.indexOf('-');
61	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
62	    }
63	
64	    private static String hash8(String value) {
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                .digest(value.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder();
69	            for (int i = 0; i < 4; i++) {
70	                sb.append(String.format("%02X", digest[i]));
71	            }
72	            return sb.toString();
73	        }
74	        catch (java.security.NoSuchAlgorithmException e) {
75	            throw new IllegalStateException(e);
76	        }
77	    }
78	}
