16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Normalises raw telephone input to E.164 form.
20	 */
21	public final class PhoneNumbers {
22	
23	    private PhoneNumbers() {
24	    }
25	
26	    /**
27	     * Convert a raw telephone string to E.164. Spaces, dashes and brackets are stripped.
28	     * A leading '+' and its country code are kept; otherwise country code '+61' is assumed
29	     * and a single leading '0' is dropped from the national digits.
30	     *
31	     * @param raw the caller-supplied telephone value
32	     * @return the E.164 representation (leading '+' followed by digits)
33	     */
34	    public static String toE164(String raw) {
35	        String digits = raw.replaceAll("\\D", "");
36	        if (raw.indexOf('+') >= 0) {
37	            return "+" + digits;
38	        }
39	        if (digits.startsWith("0")) {
40	            digits = digits.substring(1);
41	        }
42	        return "+61" + digits;
43	    }
44	
45	    /**
46	     * Format a stored E.164 number for humans: the country code, a space, then the national
47	     * digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
48	     *
49	     * @param e164 a normalised E.164 telephone (leading '+' followed by digits)
50	     * @return the human-friendly representation, or the input unchanged when blank
51	     */
52	    public static String toDisplay(String e164) {
53	        if (e164 == null || e164.isBlank()) {
54	            return e164;
55	        }
56	        int split = e164.startsWith("+1") ? 2 : 3;
57	        String national = e164.substring(split).replaceAll("(\\d{3})(?=\\d)", "$1 ");
58	        return e164.substring(0, split) + " " + national;
59	    }
60	}
