16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Derives a household's stable, shared identifier from the last name and postcode
24	 * that define it. Owners sharing a household (same last name and postcode) resolve to
25	 * the same value, so the household key is deterministic rather than explicitly linked.
26	 */
27	public final class HouseholdId {
28	
29	    private HouseholdId() {
30	    }
31	
32	    /**
33	     * @param lastName the household's last name (normalized case-insensitively)
34	     * @param postcode the household's postcode
35	     * @return a stable 12-character hex identifier, or {@code null} if either input is null
36	     */
37	    public static String of(String lastName, String postcode) {
38	        if (lastName == null || postcode == null) {
39	            return null;
40	        }
41	        String key = normalize(lastName) + "|" + postcode;
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder();
45	            for (int i = 0; i < 6; i++) {
46	                sb.append(String.format("%02X", digest[i]));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException(e);
52	        }
53	    }
54	
55	    private static String normalize(String value) {
56	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
57	    }
58	}
