16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Normalises raw postal address input: whitespace is trimmed and collapsed, the
22	 * result is upper-cased, and common abbreviations are expanded to their full words.
23	 */
24	public final class AddressNormalizer {
25	
26	    private static final Map<String, String> ABBREVIATIONS =
27	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
28	
29	    private AddressNormalizer() {
30	    }
31	
32	    /**
33	     * @param raw the caller-supplied address value
34	     * @return the normalized address, or {@code null} if {@code raw} is null
35	     */
36	    public static String normalize(String raw) {
37	        if (raw == null) {
38	            return null;
39	        }
40	        String[] tokens = raw.trim().replaceAll("\\s+", " ").toUpperCase().split(" ");
41	        StringBuilder sb = new StringBuilder();
42	        for (String token : tokens) {
43	            if (sb.length() > 0) {
44	                sb.append(' ');
45	            }
46	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
47	        }
48	        return sb.toString();
49	    }
50	}
